#include "../source/AudioReference.h"
#include <iostream>
static void require(bool ok,const char* msg){if(!ok){std::cerr<<"FAIL: "<<msg<<'\n';std::exit(1);}}
int main(){juce::ScopedJuceInitialiser_GUI init;AudioReferenceWorker::Request r;r.rate=48000;r.clip={1,0,12,3,1};r.clip.fadeIn=.1;r.clip.fadeOut=.1;r.name="Trimmed clip";for(auto& a:r.audio){a.resize(48000);for(int n=0;n<48000;++n)a[size_t(n)]=.4f*std::sin(float(n)*.057595865f);}auto before=r.audio;auto result=AudioReferenceWorker::analyse(r,[]{return false;});require(result.error.isEmpty()&&result.file.existsAsFile(),"reference written");require(result.seconds==1&&result.bpm==0,"duration and insufficient-rhythm fallback");require(result.peakDb<-7.9&&result.peakDb>-8.1&&result.rmsDb<result.peakDb,"finite peak and RMS");require(r.audio==before,"source untouched");juce::WavAudioFormat wav;auto stream=result.file.createInputStream();std::unique_ptr<juce::AudioFormatReader> reader(wav.createReaderFor(stream.release(),true));require(bool(reader)&&reader->lengthInSamples==48000,"WAV frame count");juce::AudioBuffer<float> audio(2,48000);reader->read(&audio,0,48000,0,true,true);require(std::abs(audio.getSample(0,0))<1e-6&&std::abs(audio.getSample(0,47999))<.0002,"timeline-relative fades baked in");require(std::abs(audio.getSample(0,12000)-before[0][12000])<.00001,"interior samples preserved");reader.reset();result.file.deleteFile();
 for(auto& a:r.audio)std::fill(a.begin(),a.end(),0);require(AudioReferenceWorker::analyse(r,[]{return false;}).error.isNotEmpty(),"silence rejected");r.audio[0][0]=std::numeric_limits<float>::quiet_NaN();require(AudioReferenceWorker::analyse(r,[]{return false;}).error.isNotEmpty(),"invalid samples rejected");require(AudioReferenceWorker::analyse(r,[]{return true;}).error.isNotEmpty(),"cancellation honored");
 r.clip={1,0,0,0,8};for(auto& a:r.audio){a.assign(48000*8,0);for(int n=0;n<int(a.size());++n){const int t=n%24000;if(t<1200)a[size_t(n)]=.7f*std::exp(-float(t)/200)*std::sin(float(t)*.08f);}}
 auto beat=AudioReferenceWorker::analyse(r,[]{return false;});require(beat.error.isEmpty(),"rhythmic clip analyzed");require(beat.bpm>0&&(std::abs(beat.bpm-120)<3||std::abs(beat.bpm-60)<3||std::abs(beat.bpm-240)<3),"120 BPM pulse estimate with octave tolerance");beat.file.deleteFile();std::cout<<"PASS: copied source, duration/levels, baked fades, WAV frames, silence/NaN/cancel guards and pulse-tempo estimate.\n";}
